"""Exercise errors generated by Nginx, without involving application handlers."""

import json
import sys
from urllib.error import HTTPError
from urllib.request import Request, urlopen

url, status, code = sys.argv[1:]
body = b"x" * 17000 if status == "413" else b"{}"
request = Request(url, data=body, headers={"Content-Type": "application/json"})
try:
    urlopen(request, timeout=10)
except HTTPError as response:
    assert response.code == int(status), response.code
    assert response.headers.get_content_type() == "application/json"
    assert response.headers["Cache-Control"] == "no-store"
    assert response.headers["Referrer-Policy"] == "no-referrer"
    assert response.headers["X-Content-Type-Options"] == "nosniff"
    payload = json.load(response)["error"]
    assert payload["code"] == code
    assert payload["request_id"] == response.headers["X-Request-ID"]
    assert len(payload["request_id"]) == 32
    if status == "429":
        assert response.headers["Retry-After"] == "60"
else:
    raise AssertionError("Expected a proxy error")
print(f"Proxy {status} JSON contract passed")
